package dailyassignments;

public class DailyAssignment1_ASCIICode {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		/*Write a Java program to print the ASCII value of the following characters:
A 
a 
0 
@ 
Expected Output:
ASCII value of A = 65
ASCII value of a = 97
ASCII value of 0 = 48
ASCII value of @ = 64*/
		
		
		
		char test1 = 'A';
		int value1 = test1;
		System.out.println("ASCII value of A = " +value1);
		
		char test2 = 'a';
		int value2 = test2;
		System.out.println("ASCII value of a = " +value2);
		
		char test3 = '0';
		int value3 = test3;
		System.out.println("ASCII value of 0 = " +value3);
		
		char test4 = '@';
		int value4 = test4;
		System.out.println("ASCII value of @ = " +value4);
		
		

	}

}
